        + '<text class="an-now-t" x="' + f(xk + 7) + '" y="' + f(yk + 14) + '">' + esc(A.negaraLabel) + '</text>'
        + '<text class="an-now-s" x="' + f(xk + 7) + '" y="' + f(yk + 28) + '">Current State · ' + rb(A.hrg) + '</text>'
