  let h = '<div class="ow-ph"><h5>Jumlah Pemegang Saham</h5>';
  // STATUS DATA (8 Okt 2026): ketiadaan data BUKAN nol. Bulan M terbit ±tgl 10 bulan M+1 -> bulan terbaru yang diharapkan.
  const kini = new Date(Date.now() + 7 * 3600e3), mundur = kini.getUTCDate() >= 12 ? 1 : 2;
  const harap = new Date(Date.UTC(kini.getUTCFullYear(), kini.getUTCMonth() - mundur, 1)).toISOString().slice(0, 7);
  if (!ph.length) return h + '<div class="ow-more"><b>DATA_UNAVAILABLE</b> — belum ada data jumlah pemegang saham untuk nama ini (bukan berarti nol).</div></div>';
